var btn = root.querySelector('.bfx-magnetic-btn');
var label = root.querySelector('.bfx-magnetic-label');
var arrow = root.querySelector('.bfx-magnetic-arrow');
var halo = root.querySelector('.bfx-magnetic-halo');
var reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
var tx = 0, ty = 0, x = 0, y = 0, vx = 0, vy = 0, raf = 0;
function step() {
  vx = (vx + (tx - x) * 0.18) * 0.7;
  vy = (vy + (ty - y) * 0.18) * 0.7;
  x += vx; y += vy;
  btn.style.transform = 'translate3d(' + x.toFixed(2) + 'px,' + y.toFixed(2) + 'px,0)';
  label.style.transform = 'translate3d(' + (x * 0.28).toFixed(2) + 'px,' + (y * 0.28).toFixed(2) + 'px,0)';
  arrow.style.transform = 'translate3d(' + (x * 0.62).toFixed(2) + 'px,' + (y * 0.62).toFixed(2) + 'px,0)';
  var rest = Math.abs(vx) + Math.abs(vy) + Math.abs(tx - x) + Math.abs(ty - y);
  if (rest < 0.04 && tx === 0 && ty === 0) {
    raf = 0; x = 0; y = 0; vx = 0; vy = 0;
    btn.style.transform = ''; label.style.transform = ''; arrow.style.transform = '';
    return;
  }
  raf = requestAnimationFrame(step);
}
function run() { if (!raf) raf = requestAnimationFrame(step); }
root.addEventListener('pointermove', function (e) {
  var r = btn.getBoundingClientRect();
  halo.style.setProperty('--bfx-magnetic-mx', (e.clientX - r.left) + 'px');
  halo.style.setProperty('--bfx-magnetic-my', (e.clientY - r.top) + 'px');
  if (reduce.matches) return;
  var dx = e.clientX - (r.left + r.width / 2);
  var dy = e.clientY - (r.top + r.height / 2);
  var pull = Math.max(0, 1 - Math.sqrt(dx * dx + dy * dy) / 190);
  tx = dx * 0.45 * pull;
  ty = dy * 0.55 * pull;
  run();
});
root.addEventListener('pointerleave', function () { tx = 0; ty = 0; run(); });

