var canvas = root.querySelector('.bfx-burst-canvas');
var btn = root.querySelector('.bfx-burst-btn');
var meta = root.querySelector('.bfx-burst-meta');
var ctx = canvas.getContext('2d');
var reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
var dpr = Math.min(window.devicePixelRatio || 1, 2);
var parts = [], raf = 0, count = 0;
var colors = ['#FFD166', '#FF6B6B', '#7CE3C4', '#8B7BFF', '#FFFFFF'];
function size() {
  var r = root.getBoundingClientRect();
  if (!r.width || !r.height) return;
  canvas.width = Math.round(r.width * dpr);
  canvas.height = Math.round(r.height * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}
size();
if (window.ResizeObserver) { new ResizeObserver(size).observe(root); }
function frame() {
  raf = 0;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.globalCompositeOperation = 'lighter';
  for (var i = parts.length - 1; i >= 0; i--) {
    var p = parts[i];
    p.vy += 0.13; p.vx *= 0.985; p.vy *= 0.985;
    p.x += p.vx; p.y += p.vy; p.life--;
    if (p.life <= 0) { parts.splice(i, 1); continue; }
    var a = Math.min(1, p.life / 24);
    ctx.globalAlpha = a;
    ctx.fillStyle = p.c;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r * (0.35 + a * 0.65), 0, 6.283);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  if (parts.length) raf = requestAnimationFrame(frame);
}
function spawn(ox, oy) {
  for (var i = 0; i < 44; i++) {
    var ang = Math.random() * Math.PI * 2;
    var sp = 1.4 + Math.random() * 5.6;
    parts.push({
      x: ox, y: oy,
      vx: Math.cos(ang) * sp,
      vy: Math.sin(ang) * sp - 1.5,
      r: 1.2 + Math.random() * 2.4,
      life: 38 + Math.floor(Math.random() * 46),
      c: colors[Math.floor(Math.random() * colors.length)]
    });
  }
  if (parts.length > 260) parts.splice(0, parts.length - 260);
  if (!raf) raf = requestAnimationFrame(frame);
}
btn.addEventListener('click', function (e) {
  count++;
  meta.textContent = count === 1 ? '1 cheer sent' : count + ' cheers sent';
  btn.classList.remove('bfx-burst-pulse');
  void btn.offsetWidth;
  btn.classList.add('bfx-burst-pulse');
  if (reduce.matches) return;
  var r = root.getBoundingClientRect();
  var b = btn.getBoundingClientRect();
  var ox = (e.detail > 0 && e.clientX) ? e.clientX - r.left : b.left - r.left + b.width / 2;
  var oy = (e.detail > 0 && e.clientY) ? e.clientY - r.top : b.top - r.top + b.height / 2;
  spawn(ox, oy);
});

