js:
var btn = root.querySelector('.bfx-scramble-btn');
var out = root.querySelector('.bfx-scramble-text');
var status = root.querySelector('.bfx-scramble-status');
var reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
var glyphs = '!<>-_[]{}=+*^?#%$&01/|';
var base = out.textContent.trim();
out.textContent = base;
var queue = [], frame = 0, raf = 0, done = null, back = 0;
function tick() {
  var text = '', settled = 0, i, q;
  for (i = 0; i < queue.length; i++) {
    q = queue[i];
    if (frame >= q.e) { settled++; text += q.t; }
    else if (frame >= q.s) {
      if (!q.c || Math.random() < 0.32) q.c = glyphs.charAt(Math.floor(Math.random() * glyphs.length));
      text += q.c;
    } else text += q.f;
  }
  out.textContent = text;
  if (settled === queue.length) {
    raf = 0;
    btn.classList.remove('bfx-scramble-busy');
    if (done) { var d = done; done = null; d(); }
    return;
  }
  frame++;
  raf = requestAnimationFrame(tick);
}
function scrambleTo(next, cb) {
  var from = out.textContent, len = Math.max(from.length, next.length), i;
  queue = [];
  for (i = 0; i < len; i++) {
    var s = Math.floor(Math.random() * 14);
    queue.push({ f: from.charAt(i) || ' ', t: next.charAt(i) || ' ', s: s, e: s + 8 + Math.floor(Math.random() * 16), c: '' });
  }
  if (raf) cancelAnimationFrame(raf);
  frame = 0; done = cb || null;
  if (reduce.matches) { out.textContent = next; if (done) { var d = done; done = null; d(); } return; }
  btn.classList.add('bfx-scramble-busy');
  raf = requestAnimationFrame(tick);
}
function reveal() {
  if (btn.classList.contains('bfx-scramble-open') || raf) return;
  status.textContent = 'cipher running';
  scrambleTo(base, function () { status.textContent = 'cipher idle'; });
}
btn.addEventListener('pointerenter', reveal);
btn.addEventListener('focus', reveal);
btn.addEventListener('click', function () {
  clearTimeout(back);
  btn.classList.add('bfx-scramble-open');
  status.textContent = 'key accepted';
  scrambleTo('ACCESS GRANTED ', function () {
    back = setTimeout(function () {
      btn.classList.remove('bfx-scramble-open');
      status.textContent = 'cipher idle';
      scrambleTo(base);
    }, 1500);
  });
});

