js:
var reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
var btn = root.querySelector('.bfx-glitch-btn');
var txt = root.querySelector('.bfx-glitch-text');
var timer = 0, hit = 0;
function rnd(m) { return (Math.random() * m - m / 2).toFixed(2); }
function jitter() {
  txt.style.setProperty('--bfx-glitch-x1', rnd(8) + 'px');
  txt.style.setProperty('--bfx-glitch-x2', rnd(8) + 'px');
  txt.style.setProperty('--bfx-glitch-c1', (Math.random() * 58).toFixed(1) + '%');
  txt.style.setProperty('--bfx-glitch-c2', (Math.random() * 50).toFixed(1) + '%');
}
function start() {
  if (reduce.matches || timer) return;
  jitter();
  timer = setInterval(jitter, 90);
}
function stop() {
  clearInterval(timer);
  timer = 0;
  txt.style.removeProperty('--bfx-glitch-x1');
  txt.style.removeProperty('--bfx-glitch-x2');
  txt.style.removeProperty('--bfx-glitch-c1');
  txt.style.removeProperty('--bfx-glitch-c2');
}
btn.addEventListener('pointerenter', start);
btn.addEventListener('pointerleave', stop);
btn.addEventListener('focus', start);
btn.addEventListener('blur', stop);
btn.addEventListener('click', function () {
  btn.classList.remove('bfx-glitch-hit');
  void btn.offsetWidth;
  btn.classList.add('bfx-glitch-hit');
  clearTimeout(hit);
  hit = setTimeout(function () { btn.classList.remove('bfx-glitch-hit'); }, 540);
});

