var btn = root.querySelector('.bfx-extrude-btn');
var chip = root.querySelector('.bfx-extrude-chip');
var num = root.querySelector('.bfx-extrude-count');
var n = parseInt(num.textContent, 10) || 0;
btn.addEventListener('click', function () {
  n++;
  num.textContent = n;
  chip.classList.remove('bfx-extrude-pop');
  void chip.offsetWidth;
  chip.classList.add('bfx-extrude-pop');
});
